CREATE TABLE IF NOT EXISTS public."activity_logs" (
    "id" uuid DEFAULT gen_random_uuid(),
    "user_id" uuid,
    "user_name" character varying(255) DEFAULT 'System'::character varying,
    "action" character varying(50) NOT NULL,
    "entity_type" character varying(50) NOT NULL,
    "entity_id" uuid,
    "description" text NOT NULL,
    "old_data" jsonb,
    "new_data" jsonb,
    "ip_address" character varying(45),
    "user_agent" text,
    "created_at" timestamp with time zone DEFAULT now(),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."finances" (
    "id" uuid DEFAULT gen_random_uuid(),
    "date" timestamp with time zone NOT NULL,
    "type" character varying(20) NOT NULL,
    "amount" numeric NOT NULL,
    "description" text,
    "payment_id" uuid,
    "created_at" timestamp with time zone DEFAULT now(),
    "updated_at" timestamp with time zone DEFAULT now(),
    "category" text,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."payments" (
    "id" uuid DEFAULT gen_random_uuid(),
    "student_id" uuid NOT NULL,
    "month" integer NOT NULL,
    "year" integer NOT NULL,
    "amount" numeric NOT NULL DEFAULT 0,
    "is_paid" boolean NOT NULL DEFAULT false,
    "paid_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT now(),
    "updated_at" timestamp with time zone DEFAULT now(),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."profiles" (
    "id" uuid,
    "role" text NOT NULL DEFAULT 'view'::text,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."settings" (
    "id" uuid DEFAULT gen_random_uuid(),
    "key" character varying(100) NOT NULL,
    "value" text NOT NULL,
    "description" character varying(255),
    "updated_at" timestamp with time zone DEFAULT now(),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."student_parents" (
    "id" uuid DEFAULT gen_random_uuid(),
    "student_id" uuid NOT NULL,
    "relation" text NOT NULL,
    "nik" text,
    "name" text,
    "phone" text,
    "occupation" text,
    "email" text,
    "address" text,
    "created_at" timestamp with time zone DEFAULT now(),
    "updated_at" timestamp with time zone DEFAULT now(),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."students" (
    "id" uuid DEFAULT gen_random_uuid(),
    "name" character varying(255) NOT NULL,
    "class" character varying(20) NOT NULL,
    "year_enrolled" integer NOT NULL,
    "status" character varying(20) NOT NULL DEFAULT 'active'::character varying,
    "created_at" timestamp with time zone DEFAULT now(),
    "updated_at" timestamp with time zone DEFAULT now(),
    "has_tabungan" boolean NOT NULL DEFAULT false,
    "inactive_reason" character varying(50),
    "nik" text,
    "gender" text,
    "birth_place" text,
    "birth_date" timestamp with time zone,
    "address" text,
    "phone" text,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."tabungan" (
    "id" uuid DEFAULT gen_random_uuid(),
    "student_id" uuid NOT NULL,
    "saldo" numeric NOT NULL DEFAULT 0,
    "jumlah_transaksi" integer NOT NULL DEFAULT 0,
    "updated_at" timestamp with time zone DEFAULT now(),
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS public."tabungan_transaksi" (
    "id" uuid DEFAULT gen_random_uuid(),
    "student_id" uuid NOT NULL,
    "tanggal" timestamp with time zone NOT NULL DEFAULT now(),
    "jenis" character varying(10) NOT NULL,
    "nominal" numeric NOT NULL,
    "keterangan" text,
    "saldo_setelah" numeric,
    "created_at" timestamp with time zone DEFAULT now(),
    PRIMARY KEY ("id")
);



