CREATE INDEX idx_finances_category ON public.finances USING btree (category);
CREATE INDEX idx_finances_date ON public.finances USING btree (date);
CREATE INDEX idx_finances_payment_id ON public.finances USING btree (payment_id);
CREATE INDEX idx_finances_type ON public.finances USING btree (type);
CREATE INDEX idx_logs_action ON public.activity_logs USING btree (action);
CREATE INDEX idx_logs_date ON public.activity_logs USING btree (created_at DESC);
CREATE INDEX idx_logs_description ON public.activity_logs USING gin (to_tsvector('indonesian'::regconfig, description));
CREATE INDEX idx_logs_entity ON public.activity_logs USING btree (entity_type, entity_id);
CREATE INDEX idx_logs_user ON public.activity_logs USING btree (user_id);
